class Completed {

    public double myPow(double x, int n) {

        long power = n;

        if (power < 0) {

            x = 1.0 / x;
            power = -power;
        }

        double result = 1.0;

        while (power > 0) {

            if ((power & 1L) == 1L) {
                result *= x;
            }

            x *= x;
            power >>= 1;
        }

        return result;
    }
}

